import { fetch } from '@gsm-app/utils/fetch';
import { createError } from '@gsm-common/utils/toast/createError';
import { useQuery } from '@tanstack/react-query';
import { useEffect, useMemo } from 'react';

interface NgpConfigResponse {
    data?: {
        Resolution?: string;
        FrameRate?: string;
    };
    errors?: {
        title: string;
        detail: string;
    }[];
}

export interface NgpConfig {
    resolution?: number;
    fps?: number;
}

export const NGP_CONFIG_QUERY_KEY = 'ngpConfig';

export const useNgpConfig = (gameId?: string) => {
    const query = useQuery<NgpConfigResponse>({
        queryKey: [NGP_CONFIG_QUERY_KEY, gameId],
        enabled: Boolean(gameId),
        queryFn: async () => {
            const response = await fetch(`/api/game/config?gameId=${gameId}`);
            return await response.json();
        },
    });

    const ngpConfig = useMemo<NgpConfig>(() => {
        if (!query.data?.data) {
            return {};
        }

        const config: NgpConfig = {};

        // Parse and validate Resolution
        if (query.data.data.Resolution) {
            const parsedResolution = Number.parseInt(query.data.data.Resolution, 10);
            if ([720, 1080].includes(parsedResolution)) {
                config.resolution = parsedResolution;
            }
        }

        // Parse and validate FrameRate
        if (query.data.data.FrameRate) {
            const parsedFps = Number.parseInt(query.data.data.FrameRate, 10);
            if ([30, 60].includes(parsedFps)) {
                config.fps = parsedFps;
            }
        }

        return config;
    }, [query.data]);

    const { error, isError } = query;
    useEffect(() => {
        if (isError && gameId) {
            createError({
                title: 'Error Loading NGP Config',
                body: `Failed to load video defaults for game ${gameId}: ${error?.message}`,
                options: {
                    id: `ngp-config-fetch-error-${gameId}`,
                    duration: 3000,
                },
            });
        }
        if (query.data?.errors) {
            query.data?.errors.forEach((e) => {
                createError({
                    title: e.title,
                    body: e.detail,
                    options: {
                        duration: 3000,
                        id: `ngp-config-fetch-error-${gameId}-${e.title}`,
                    },
                });
            });
        }
    }, [query.data, error, isError, gameId]);

    return {
        ...query,
        data: ngpConfig,
    };
};
